import { defineConfig, type Plugin } from 'vite';
import react from '@vitejs/plugin-react';
import tailwindcss from '@tailwindcss/vite';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const __dirname = path.dirname(fileURLToPath(import.meta.url));

// App name comes from the card (generated by scripts/card.mjs) — injected into <title>.
const card = JSON.parse(fs.readFileSync(path.resolve(__dirname, 'src/card.generated.json'), 'utf8'));
const cardTitle = (): Plugin => ({
  name: 'card-title',
  transformIndexHtml: (html) => html.replace(/%APP_NAME%/g, card.appName),
});

export default defineConfig({
  plugins: [react(), tailwindcss(), cardTitle()],
  server: {
    port: 4316,
    strictPort: true,
    proxy: {
      '/api': { target: 'http://localhost:4317', changeOrigin: false },
      '/pty': { target: 'ws://localhost:4317', ws: true },
    },
  },
  build: {
    // picker.html is a dev-only entry (served by `vite` dev server); production builds only the app.
    rollupOptions: { input: { main: path.resolve(__dirname, 'index.html') } },
  },
});
